package net.civeira.phylax.feature.identity.tenantconfig.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class RefreshTokenMaxLifetimeSecondsVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property refresh token max lifetime seconds of tenant config ")
  void test_refresh_token_max_lifetime_seconds_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class,
        () -> RefreshTokenMaxLifetimeSecondsVO.tryFrom(null));
    Assertions.assertEquals(1,
        RefreshTokenMaxLifetimeSecondsVO.from(1).getRefreshTokenMaxLifetimeSeconds());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> RefreshTokenMaxLifetimeSecondsVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + 1 + "]", RefreshTokenMaxLifetimeSecondsVO.from(1).toString());
  }
}
